class TrieNode { constructor(){ this.next=new Map(); this.pass=0; this.end=0; } }
class Trie {
  constructor(){ this.root=new TrieNode(); }
  addWord(w){ let node=this.root; node.pass++; for(const ch of w){ if(!node.next.has(ch)) node.next.set(ch,new TrieNode()); node=node.next.get(ch); node.pass++; } node.end++; }
  removeWord(w){ let stack=[]; let node=this.root; stack.push(node); for(const ch of w){ if(!node.next.has(ch)) return; node=node.next.get(ch); stack.push(node); } if(stack[stack.length-1].end===0) return; stack.forEach(n=>n.pass--); stack[stack.length-1].end--; }
  countPrefix(p){ let node=this.root; for(const ch of p){ if(!node.next.has(ch)) return 0; node=node.next.get(ch); } return node.pass; }
}
```

